INSERT INTO Categories (Name) VALUES ('Tecnologia'), ('Literatura') ON DUPLICATE KEY UPDATE Name=VALUES(Name);
INSERT INTO Authors (Name) VALUES ('Robert C. Martin'), ('Machado de Assis') ON DUPLICATE KEY UPDATE Name=VALUES(Name);
INSERT INTO Publishers (Name) VALUES ('Prentice Hall'), ('Companhia das Letras') ON DUPLICATE KEY UPDATE Name=VALUES(Name);
INSERT INTO Genres (Name) VALUES ('Programação'), ('Romance') ON DUPLICATE KEY UPDATE Name=VALUES(Name);
INSERT INTO Books (Title, Isbn13, CategoryId, PublisherId) SELECT 'Clean Code','9780132350884',c.CategoryId,p.PublisherId FROM Categories c JOIN Publishers p ON p.Name='Prentice Hall' WHERE c.Name='Tecnologia' AND NOT EXISTS (SELECT 1 FROM Books WHERE Isbn13='9780132350884');
INSERT INTO Books (Title, Isbn13, CategoryId, PublisherId) SELECT 'Dom Casmurro','9788535910663',c.CategoryId,p.PublisherId FROM Categories c JOIN Publishers p ON p.Name='Companhia das Letras' WHERE c.Name='Literatura' AND NOT EXISTS (SELECT 1 FROM Books WHERE Isbn13='9788535910663');
INSERT IGNORE INTO BookAuthors SELECT b.BookId,a.AuthorId FROM Books b JOIN Authors a ON (b.Title='Clean Code' AND a.Name='Robert C. Martin') OR (b.Title='Dom Casmurro' AND a.Name='Machado de Assis');
INSERT IGNORE INTO BookGenres SELECT b.BookId,g.GenreId FROM Books b JOIN Genres g ON (b.Title='Clean Code' AND g.Name='Programação') OR (b.Title='Dom Casmurro' AND g.Name='Romance');
INSERT IGNORE INTO Copies (BookId,InventoryCode) SELECT BookId,'EX-CLEAN-001' FROM Books WHERE Isbn13='9780132350884';
INSERT IGNORE INTO Copies (BookId,InventoryCode) SELECT BookId,'EX-DOM-001' FROM Books WHERE Isbn13='9788535910663';
INSERT INTO Readers (FullName,RegistrationNumber) VALUES ('Leitor Demonstração','MAT-0001') ON DUPLICATE KEY UPDATE RegistrationNumber=VALUES(RegistrationNumber);
INSERT INTO Categories (Name) VALUES ('Ciências Humanas'), ('Infantil') ON DUPLICATE KEY UPDATE Name=VALUES(Name);
INSERT INTO Authors (Name) VALUES ('Yuval Noah Harari'), ('Monteiro Lobato'), ('Martin Fowler') ON DUPLICATE KEY UPDATE Name=VALUES(Name);
INSERT INTO Publishers (Name) VALUES ('Companhia das Letras'), ('Editora 34'), ('Pearson') ON DUPLICATE KEY UPDATE Name=VALUES(Name);
INSERT INTO Genres (Name) VALUES ('História'), ('Infantil'), ('Engenharia de Software') ON DUPLICATE KEY UPDATE Name=VALUES(Name);
INSERT INTO Books (Title, Isbn13, CategoryId, PublisherId) SELECT 'Sapiens','9788535920171',c.CategoryId,p.PublisherId FROM Categories c JOIN Publishers p ON p.Name='Companhia das Letras' WHERE c.Name='Ciências Humanas' AND NOT EXISTS (SELECT 1 FROM Books WHERE Isbn13='9788535920171');
INSERT INTO Books (Title, Isbn13, CategoryId, PublisherId) SELECT 'O Sítio do Picapau Amarelo','9788525056455',c.CategoryId,p.PublisherId FROM Categories c JOIN Publishers p ON p.Name='Editora 34' WHERE c.Name='Infantil' AND NOT EXISTS (SELECT 1 FROM Books WHERE Isbn13='9788525056455');
INSERT INTO Books (Title, Isbn13, CategoryId, PublisherId) SELECT 'Refatoração','9788577807479',c.CategoryId,p.PublisherId FROM Categories c JOIN Publishers p ON p.Name='Pearson' WHERE c.Name='Tecnologia' AND NOT EXISTS (SELECT 1 FROM Books WHERE Isbn13='9788577807479');
INSERT IGNORE INTO BookAuthors SELECT b.BookId,a.AuthorId FROM Books b JOIN Authors a ON (b.Title='Sapiens' AND a.Name='Yuval Noah Harari') OR (b.Title='O Sítio do Picapau Amarelo' AND a.Name='Monteiro Lobato') OR (b.Title='Refatoração' AND a.Name='Martin Fowler');
INSERT IGNORE INTO BookGenres SELECT b.BookId,g.GenreId FROM Books b JOIN Genres g ON (b.Title='Sapiens' AND g.Name='História') OR (b.Title='O Sítio do Picapau Amarelo' AND g.Name='Infantil') OR (b.Title='Refatoração' AND g.Name='Engenharia de Software');
INSERT IGNORE INTO Copies (BookId,InventoryCode) SELECT BookId,'EX-SAPIENS-001' FROM Books WHERE Isbn13='9788535920171';
INSERT IGNORE INTO Copies (BookId,InventoryCode) SELECT BookId,'EX-SITIO-001' FROM Books WHERE Isbn13='9788525056455';
INSERT IGNORE INTO Copies (BookId,InventoryCode) SELECT BookId,'EX-REFATOR-001' FROM Books WHERE Isbn13='9788577807479';
INSERT INTO Readers (FullName,RegistrationNumber,IsSuspended) VALUES ('Ana Souza','MAT-0002',FALSE), ('Bruno Lima','MAT-0003',TRUE), ('Carla Mendes','MAT-0004',FALSE) ON DUPLICATE KEY UPDATE FullName=VALUES(FullName), IsSuspended=VALUES(IsSuspended);
INSERT INTO Loans (CopyId,ReaderId,LoanedAt,DueAt,ReturnedAt) SELECT cp.CopyId,r.ReaderId,DATE_SUB(UTC_TIMESTAMP(),INTERVAL 25 DAY),DATE_SUB(UTC_TIMESTAMP(),INTERVAL 11 DAY),NULL FROM Copies cp JOIN Readers r ON r.RegistrationNumber='MAT-0002' WHERE cp.InventoryCode='EX-SAPIENS-001' AND NOT EXISTS (SELECT 1 FROM Loans l WHERE l.CopyId=cp.CopyId AND l.ReturnedAt IS NULL);
INSERT INTO Reservations (BookId,ReaderId,Status) SELECT b.BookId,r.ReaderId,'ACTIVE' FROM Books b JOIN Readers r ON r.RegistrationNumber='MAT-0004' WHERE b.Isbn13='9788535920171' AND NOT EXISTS (SELECT 1 FROM Reservations x WHERE x.BookId=b.BookId AND x.ReaderId=r.ReaderId AND x.Status='ACTIVE');
INSERT INTO Fines (LoanId,Amount,Reason) SELECT l.LoanId,15.00,'Atraso na devolução' FROM Loans l WHERE l.ReturnedAt IS NULL AND NOT EXISTS (SELECT 1 FROM Fines f WHERE f.LoanId=l.LoanId);
